    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The lone marker on an edge signals that the adjacent rectangular
    # region made of the other color should be filled with 1.
    counts = {}
    for row in out:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = [(r, c) for r in range(h) for c in range(w)
               if out[r][c] not in (background, 1)]
    if not markers:
        return out
    r, c = markers[0]
    # For these patterns, the marker's row/column lies on the outer edge;
    # fill the inward contiguous non-background rectangle until a separator.
    if r == 0:
        out[0][c] = 1
        for rr in range(1, h):
            if all(x == background for x in out[rr]):
                break
            for cc in range(c, w):
                if out[rr][cc] != background:
                    out[rr][cc] = 1
    return out
